def main() -> None:
    path = ROOT / "content" / "posts.json"
    posts = json.loads(path.read_text(encoding="utf-8"))
    for post in posts:
        title, summary, intro, sections, takeaway_title, takeaway = EDITION[post["slug"]]
        post["title"] = title
        post["summary"] = summary
        post["seo_title"] = title
        post["intro"] = [intro]
        post["sections"] = [
            {"heading": heading, "paragraphs": [paragraph], "bullets": bullets}
            for heading, paragraph, bullets in sections
        ]
        post["takeaway_title"] = takeaway_title
        post["takeaway"] = takeaway
        post["subject"] = f"استفسار حول {title}"
        post["published"] = "2026-10-18"
        if post.get("featured"):
            post["featured"]["alt"] = f"صورة توضيحية لمقال {title} من بصمة لحلول التقنية"
    path.write_text(json.dumps(posts, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Rewrote {len(posts)} Bsmah posts")


if __name__ == "__main__":
    main()
